/**
 * API for jsb module
 * Author: haroel
 * Homepage: https://github.com/haroel/creatorexDTS
 */
declare namespace jsb{
    /**
     * Low memory warning levels
     *
     * These levels correspond to Android's ComponentCallbacks2.onTrimMemory() callback levels.
     *
     * @see https://developer.android.com/reference/android/content/ComponentCallbacks2
     */
    export enum LowMemoryLevel {
        /**
         * The device is running moderately low on memory (Deprecated since Android API 34)
         */
        RUNNING_MODERATE = 5,

        /**
         * The device is running low on memory (Deprecated since Android API 34)
         */
        RUNNING_LOW = 10,

        /**
         * The device is running extremely low on memory (Deprecated since Android API 34)
         */
        RUNNING_CRITICAL = 15,

        /**
         * The app's UI is no longer visible
         */
        UI_HIDDEN = 20,

        /**
         * The app is now in the background LRU list
         */
        BACKGROUND = 40,

        /**
         * The app is in the middle of the background LRU list
         */
        MODERATE = 60,

        /**
         * The app is near the end of the background LRU list
         */
        COMPLETE = 80
    }

    export module reflection{
        /**
         * https://docs.cocos.com/creator/manual/zh/advanced-topics/java-reflection.html
         * call OBJC/Java static methods
         *
         * @param className
         * @param methodName
         * @param methodSignature
         * @param parameters
         */
        export function callStaticMethod (className: string, methodName: string, methodSignature: string, ...parameters:any): any;
    }

    /**
     * 下载客户端类
     *
     * @description 提供文件和数据下载功能，支持断点续传、优先级控制、进度回调等特性
     *
     * @example
     * ```javascript
     * const client = new jsb.DownloadClient({
     *     maxConcurrentTasks: 5,
     *     userAgent: "MyApp/1.0",
     *     enableResume: true
     * });
     *
     * const taskId = client.downloadFile({
     *     url: "https://example.com/file.zip",
     *     path: "/path/to/save",
     *     success: (taskId, url, path, totalBytes, elapsedMs) => {
     *         console.log(`下载完成: ${path}`);
     *     },
     *     failure: (taskId, url, code, httpStatus, msg) => {
     *         console.error(`下载失败: ${msg}`);
     *     },
     *     progress: (taskId, url, receivedBytes, total) => {
     *         console.log(`进度: ${(receivedBytes/total*100).toFixed(1)}%`);
     *     }
     * });
     * ```
     */
    export class DownloadClient {

        /**
         * 创建下载客户端实例
         * @param config 可选的客户端配置
         */
        constructor(config?: DownloadClient.ClientConfig);

        /**
         * 下载错误码枚举
         *
         * @description 定义所有可能的下载错误类型
         */
        static ErrorCode: {
            NONE: 0;
            INVALID_URL: -1;
            INVALID_PATH: -2;
            INVALID_PARAMS: -3;
            NETWORK: -4;
            TIMEOUT: -5;
            CANCELLED: -6;
            FILE_IO: -7;
            DISK_FULL: -8;
            PERMISSION: -9;
            HTTP_4XX: -10;
            HTTP_5XX: -11;
            OUT_OF_MEMORY: -12;
            UNKNOWN: -99;
        };

        /**
         * 下载文件到本地磁盘
         *
         * @param options 下载选项，包括 URL、保存路径、回调函数等
         * @returns 任务 ID，用于标识和控制下载任务；如果创建失败返回 -1
         *
         * @description
         * - 支持断点续传（通过 enableResume 选项）
         * - 支持自定义 HTTP 请求头
         * - 支持优先级控制
         * - 所有回调函数都在主线程（Cocos 线程）执行
         */
        downloadFile(options: DownloadClient.DownloadFileOption): number;

        /**
         * 下载数据到内存
         *
         * @param options 下载选项，包括 URL、回调函数等
         * @returns 任务 ID，用于标识和控制下载任务；如果创建失败返回 -1
         *
         * @description
         * - 数据以 ArrayBuffer 形式返回
         * - 适用于小文件或需要直接处理数据的场景
         * - 不支持断点续传
         * - 所有回调函数都在主线程（Cocos 线程）执行
         */
        downloadData(options: DownloadClient.DownloadDataOption): number;

        /**
         * 取消下载任务
         *
         * @param taskId 要取消的任务 ID
         * @param removeTmpFile 是否删除临时文件（默认 false）
         * @returns 是否成功取消任务
         *
         * @description
         * - 如果任务不存在或已完成，返回 false
         * - 取消后会触发 fail 回调，错误码为 ERROR_CANCELLED
         */
        abort(taskId: number, removeTmpFile?: boolean): boolean;
    }

    export namespace DownloadClient {

        /**
         * 错误码值类型（用于类型安全的错误码比较）
         *
         * @example
         * ```typescript
         * function handleError(code: jsb.DownloadClient.ErrorCodeValue) {
         *     if (code === jsb.DownloadClient.ErrorCode.ERROR_NETWORK) {
         *         console.log("网络错误");
         *     }
         * }
         * ```
         */
        export type ErrorCodeValue = typeof DownloadClient.ErrorCode[keyof typeof DownloadClient.ErrorCode];

        /**
         * 客户端配置选项
         */
        export interface ClientConfig {
            /** 最大并发任务数（默认: 6） */
            maxConcurrentTasks?: number;
            /** User-Agent 字符串（默认: "DownloadClient/2.0"） */
            userAgent?: string;
            /** 是否启用断点续传（默认: true） */
            enableResume?: boolean;
            /** 内存缓存最大大小，单位字节（默认: 100MB） */
            maxMemoryCacheSize?: number;
        }

        /**
         * 文件下载选项
         */
        export interface DownloadFileOption {
            /** 下载 URL（必填，不能为空） */
            url: string;
            /** 本地存储路径（必填，不能为空） */
            path: string;
            /** 自定义 HTTP 请求头（可选） */
            headers?: Record<string, string>;
            /** 超时时间（秒），0 表示使用默认值（可选） */
            timeoutSeconds?: number;
            /** 优先级：-1=低，0=默认，1-5=高（值越大优先级越高，可选，当前仅 iOS 生效，Android 为 FIFO 模式） */
            /*priority?: number;*/
            /** 是否启用断点续传（可选，默认继承客户端配置） */
            enableResume?: boolean;
            /**
             * 下载成功回调（必填）
             * @param taskId 任务 ID
             * @param requestURL 请求的 URL
             * @param storagePath 存储路径
             * @param totalBytes 总字节数
             * @param elapsedMs 总耗时（毫秒）
             */
            success: (taskId: number, requestURL: string, storagePath: string, totalBytes: number, elapsedMs: number) => void;
            /**
             * 下载失败回调（必填）
             * @param taskId 任务 ID
             * @param requestURL 请求的 URL
             * @param errorCode 错误码（DownloadClient.ErrorCode）
             * @param httpStatus HTTP 状态码（如适用）
             * @param errorStr 错误信息
             */
            failure: (taskId: number, requestURL: string, errorCode: number, httpStatus: number, errorStr: string) => void;
            /**
             * 下载进度回调（必填）
             * @param taskId 任务 ID
             * @param requestURL 请求的 URL
             * @param receivedBytes 已接收字节数（累计）
             * @param totalBytes 总字节数（期望）
             */
            progress: (taskId: number, requestURL: string, receivedBytes: number, totalBytes: number) => void;
        }

        /**
         * 数据下载选项
         */
        export interface DownloadDataOption {
            /** 下载 URL（必填，不能为空） */
            url: string;
            /** 自定义 HTTP 请求头（可选） */
            headers?: Record<string, string>;
            /** 超时时间（秒），0 表示使用默认值（可选） */
            timeoutSeconds?: number;
            /** 优先级：-1=低，0=默认，1-5=高（值越大优先级越高，可选） */
            priority?: number;
            /**
             * 下载成功回调（必填）
             * @param taskId 任务 ID
             * @param requestURL 请求的 URL
             * @param data 下载的数据（ArrayBuffer）
             * @param totalBytes 总字节数
             * @param elapsedMs 总耗时（毫秒）
             */
            success: (taskId: number, requestURL: string, data: ArrayBuffer, totalBytes: number, elapsedMs: number) => void;
            /**
             * 下载失败回调（必填）
             * @param taskId 任务 ID
             * @param requestURL 请求的 URL
             * @param errorCode 错误码（DownloadClient.ErrorCode）
             * @param httpStatus HTTP 状态码（如适用）
             * @param errorStr 错误信息
             */
            failure: (taskId: number, requestURL: string, errorCode: number, httpStatus: number, errorStr: string) => void;
            /**
             * 下载进度回调（必填）
             * @param taskId 任务 ID
             * @param requestURL 请求的 URL
             * @param receivedBytes 已接收字节数（累计）
             * @param totalBytes 总字节数（期望）
             */
            progress: (taskId: number, requestURL: string, receivedBytes: number, totalBytes: number) => void;
        }
    }

    /**
     * 下载任务对象
     */
    export type DownloaderTask = { requestURL: string, storagePath: string, identifier: string };

    /**
     * Http file downloader for jsb！
     */
    export class Downloader{
        /**
         * create a download task
         * @param requestURL
         * @param storagePath
         * @param identifier
         */
        createDownloadFileTask (requestURL:string, storagePath:string, identifier?:string): DownloaderTask;

        setOnFileTaskSuccess (onSucceed: (task: DownloaderTask) => void): void;

        setOnTaskProgress (onProgress: (task: DownloaderTask, bytesReceived: number, totalBytesReceived: number, totalBytesExpected: number) => void): void;

        setOnTaskError (onError: (task: DownloaderTask, errorCode: number, errorCodeInternal: number, errorStr: string) => void): void;

    }

    export interface ManifestAsset {
        md5: string;
        path: string;
        compressed: boolean;
        size: number;
        downloadState: number;
    }

    export class Manifest {
        constructor (manifestUrl: string);
        constructor (content: string, manifestRoot: string);
        parseFile (manifestUrl: string): void;
        parseJSONString (content: string, manifestRoot: string): void;

        getManifestRoot (): string;
        getManifestFileUrl (): string;
        getVersionFileUrl (): string;
        getSearchPaths (): [string];
        getVersion (): string;
        getPackageUrl (): boolean;

        setUpdating (isUpdating: boolean): void;
        isUpdating (): boolean;
        isVersionLoaded (): boolean;
        isLoaded (): boolean;
    }

    export class EventAssetsManager {
        // EventCode
        static ERROR_NO_LOCAL_MANIFEST: number;
        static ERROR_DOWNLOAD_MANIFEST: number;
        static ERROR_PARSE_MANIFEST: number;
        static NEW_VERSION_FOUND: number;
        static ALREADY_UP_TO_DATE: number;
        static UPDATE_PROGRESSION: number;
        static ASSET_UPDATED: number;
        static ERROR_UPDATING: number;
        static UPDATE_FINISHED: number;
        static UPDATE_FAILED: number;
        static ERROR_DECOMPRESS: number;
        static STOP_WHENUPDATE: number;

        constructor (eventName: string, manager: AssetsManager, eventCode: number,
                    assetId?: string, message?: string, curleCode?: number, curlmCode?: number);
        getAssetsManagerEx (): AssetsManager;
        isResuming (): boolean;

        getDownloadedFiles (): number;
        getDownloadedBytes (): number;
        getTotalFiles (): number;
        getTotalBytes (): number;
        getPercent (): number;
        getPercentByFile (): number;

        getEventCode (): number;
        getMessage (): string;
        getAssetId (): string;
        getCURLECode (): number;
        getCURLMCode (): number;
    }

    export module AssetsManager {
        export enum State {
            UNINITED,
            UNCHECKED,
            PREDOWNLOAD_VERSION,
            DOWNLOADING_VERSION,
            VERSION_LOADED,
            PREDOWNLOAD_MANIFEST,
            DOWNLOADING_MANIFEST,
            MANIFEST_LOADED,
            NEED_UPDATE,
            READY_TO_UPDATE,
            UPDATING,
            UNZIPPING,
            UP_TO_DATE,
            FAIL_TO_UPDATE,
        }
    }

    export class AssetsManager {
        constructor (manifestUrl: string, storagePath: string, versionCompareHandle?: (versionA: string, versionB: string) => number);
        static create (manifestUrl: string, storagePath: string): AssetsManager;

        getState (): AssetsManager.State;
        getStoragePath (): string
        getMaxConcurrentTask (): number;
        // setMaxConcurrentTask (max: number): void;  // actually not supported

        checkUpdate (): void;
        prepareUpdate (): void;
        update (): void;
        isResuming (): boolean;

        getDownloadedFiles (): number;
        getDownloadedBytes (): number;
        getTotalFiles (): number;
        getTotalBytes (): number;
        downloadFailedAssets (): void;

        getLocalManifest (): Manifest;
        loadLocalManifest (manifestUrl: string): boolean;
        loadLocalManifest (localManifest: Manifest, storagePath: string): boolean;
        getRemoteManifest (): Manifest;
        loadRemoteManifest (remoteManifest: Manifest): boolean;

        /**
         * Setup your own version compare handler, versionA and B is versions in string.
         * if the return value greater than 0, versionA is greater than B,
         * if the return value equals 0, versionA equals to B,
         * if the return value smaller than 0, versionA is smaller than B.
         */
        setVersionCompareHandle (versionCompareHandle?: (versionA: string, versionB: string) => number): void;
        /**
         * Setup the verification callback, Return true if the verification passed, otherwise return false
         */
        setVerifyCallback (verifyCallback: (path: string, asset: ManifestAsset) => boolean): void;
        setEventCallback (eventCallback: (event: EventAssetsManager) => void): void;
    }

    /**
     * FileUtils  Helper class to handle file operations.
     */
    export module fileUtils{
        /**
         *  Checks whether the path is an absolute path.
         *
         *  @note On Android, if the parameter passed in is relative to "@assets/", this method will treat it as an absolute path.
         *        Also on Blackberry, path starts with "app/native/Resources/" is treated as an absolute path.
         *
         *  @param path The path that needs to be checked.
         *  @return True if it's an absolute path, false if not.
         */
        export function isAbsolutePath (path:string):boolean;
        /** Returns the fullpath for a given filename.

        First it will try to get a new filename from the "filenameLookup" dictionary.
        If a new filename can't be found on the dictionary, it will use the original filename.
        Then it will try to obtain the full path of the filename using the FileUtils search rules: resolutions, and search paths.
        The file search is based on the array element order of search paths and resolution directories.

        For instance:

            We set two elements("/mnt/sdcard/", "internal_dir/") to search paths vector by setSearchPaths,
            and set three elements("resources-ipadhd/", "resources-ipad/", "resources-iphonehd")
            to resolutions vector by setSearchResolutionsOrder. The "internal_dir" is relative to "Resources/".

            If we have a file named 'sprite.png', the mapping in fileLookup dictionary contains `key: sprite.png -> value: sprite.pvr.gz`.
            Firstly, it will replace 'sprite.png' with 'sprite.pvr.gz', then searching the file sprite.pvr.gz as follows:

                /mnt/sdcard/resources-ipadhd/sprite.pvr.gz      (if not found, search next)
                /mnt/sdcard/resources-ipad/sprite.pvr.gz        (if not found, search next)
                /mnt/sdcard/resources-iphonehd/sprite.pvr.gz    (if not found, search next)
                /mnt/sdcard/sprite.pvr.gz                       (if not found, search next)
                internal_dir/resources-ipadhd/sprite.pvr.gz     (if not found, search next)
                internal_dir/resources-ipad/sprite.pvr.gz       (if not found, search next)
                internal_dir/resources-iphonehd/sprite.pvr.gz   (if not found, search next)
                internal_dir/sprite.pvr.gz                      (if not found, return "sprite.png")

            If the filename contains relative path like "gamescene/uilayer/sprite.png",
            and the mapping in fileLookup dictionary contains `key: gamescene/uilayer/sprite.png -> value: gamescene/uilayer/sprite.pvr.gz`.
            The file search order will be:

                /mnt/sdcard/gamescene/uilayer/resources-ipadhd/sprite.pvr.gz      (if not found, search next)
                /mnt/sdcard/gamescene/uilayer/resources-ipad/sprite.pvr.gz        (if not found, search next)
                /mnt/sdcard/gamescene/uilayer/resources-iphonehd/sprite.pvr.gz    (if not found, search next)
                /mnt/sdcard/gamescene/uilayer/sprite.pvr.gz                       (if not found, search next)
                internal_dir/gamescene/uilayer/resources-ipadhd/sprite.pvr.gz     (if not found, search next)
                internal_dir/gamescene/uilayer/resources-ipad/sprite.pvr.gz       (if not found, search next)
                internal_dir/gamescene/uilayer/resources-iphonehd/sprite.pvr.gz   (if not found, search next)
                internal_dir/gamescene/uilayer/sprite.pvr.gz                      (if not found, return "gamescene/uilayer/sprite.png")

        If the new file can't be found on the file system, it will return the parameter filename directly.

        This method was added to simplify multiplatform support. Whether you are using cocos2d-js or any cross-compilation toolchain like StellaSDK or Apportable,
        you might need to load different resources for a given file in the different platforms.

        @since v2.1
        */
        export function fullPathForFilename (filename:string):string;
        /**
         *  Gets string from a file.
        */
        export function getStringFromFile (filename:string):string;
        /**
         *  Removes a file.
         *
         *  @param filepath The full path of the file, it must be an absolute path.
         *  @return True if the file have been removed successfully, false if not.
         */
        export function removeFile (filepath:string):boolean;
        /**
         *  Checks whether the path is a directory.
         *
         *  @param dirPath The path of the directory, it could be a relative or an absolute path.
         *  @return True if the directory exists, false if not.
         */
        export function isDirectoryExist (dirPath:string):boolean;
        /**
         * Normalize: remove . and ..
         * @param filepath
         */
        export function normalizePath (filepath:string):string;
        /**
         * Get default resource root path.
         */
        export function getDefaultResourceRootPath ():string;
        /**
         * Loads the filenameLookup dictionary from the contents of a filename.
         *
         * @note The plist file name should follow the format below:
         *
         * @code
         * <?xml version="1.0" encoding="UTF-8"?>
         * <!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
         * <plist version="1.0">
         * <dict>
         *     <key>filenames</key>
         *     <dict>
         *         <key>sounds/click.wav</key>
         *         <string>sounds/click.caf</string>
         *         <key>sounds/endgame.wav</key>
         *         <string>sounds/endgame.caf</string>
         *         <key>sounds/gem-0.wav</key>
         *         <string>sounds/gem-0.caf</string>
         *     </dict>
         *     <key>metadata</key>
         *     <dict>
         *         <key>version</key>
         *         <integer>1</integer>
         *     </dict>
         * </dict>
         * </plist>
         * @endcode
         * @param filename The plist file name.
         *
         @since v2.1
        * @js loadFilenameLookup
        * @lua loadFilenameLookup
        */
        export function loadFilenameLookup (filepath:string):void;
        /** Checks whether to pop up a message box when failed to load an image.
         *  @return True if pop up a message box when failed to load an image, false if not.
         */
        export function isPopupNotify ():boolean;
        /**
         *  Sets whether to pop-up a message box when failed to load an image.
         */
        export function setPopupNotify (notify:boolean):void;

        // Converts the contents of a file to a ValueVector.
        // This method is used internally.
        export function getValueVectorFromFile (filepath:string):Array<any>;
        /**
         *  Gets the array of search paths.
         *
         *  @return The array of search paths which may contain the prefix of default resource root path.
         *  @note In best practise, getter function should return the value of setter function passes in.
         *        But since we should not break the compatibility, we keep using the old logic.
         *        Therefore, If you want to get the original search paths, please call 'getOriginalSearchPaths()' instead.
         *  @see fullPathForFilename(const char*).
         *  @lua NA
         */
        export function getSearchPaths ():Array<string>;
        /**
         *
         * @param filepath
         */
        export function getFileDir (filepath:string):string;
        /**
        * write a ValueMap into a plist file
        *
        *@param dict the ValueMap want to save (key,value)
        *@param fullPath The full path to the file you want to save a string
        *@return bool
        */
        export function writeToFile ( valueMap:any ):boolean;
        /**
         *  Gets the original search path array set by 'setSearchPaths' or 'addSearchPath'.
         *  @return The array of the original search paths
         */
        export function getOriginalSearchPaths ():Array<string>;
        /**
         *  List all files in a directory.
         *
         *  @param dirPath The path of the directory, it could be a relative or an absolute path.
         *  @return File paths in a string vector
         */
        export function listFiles (filepath:string):Array<string>;
        /**
         *  Converts the contents of a file to a ValueMap.
         *  @param filename The filename of the file to gets content.
         *  @return ValueMap of the file contents.
         *  @note This method is used internally.
         */
        export function getValueMapFromFile (filepath:string):any;
        /**
         *  Retrieve the file size.
         *
         *  @note If a relative path was passed in, it will be inserted a default root path at the beginning.
         *  @param filepath The path of the file, it could be a relative or absolute path.
         *  @return The file size.
         */
        export function getFileSize (filepath:string):number;

        /** Converts the contents of a file to a ValueMap.
         *  This method is used internally.
         */
        export function getValueMapFromData (filedata:string,filesize:number):any;
        /**
         *  Removes a directory.
         *
         *  @param dirPath  The full path of the directory, it must be an absolute path.
         *  @return True if the directory have been removed successfully, false if not.
         */
        export function removeDirectory (dirPath:string):boolean;
        /**
         *  Sets the array of search paths.
         *
         *  You can use this array to modify the search path of the resources.
         *  If you want to use "themes" or search resources in the "cache", you can do it easily by adding new entries in this array.
         *
         *  @note This method could access relative path and absolute path.
         *        If the relative path was passed to the vector, FileUtils will add the default resource directory before the relative path.
         *        For instance:
         *            On Android, the default resource root path is "@assets/".
         *            If "/mnt/sdcard/" and "resources-large" were set to the search paths vector,
         *            "resources-large" will be converted to "@assets/resources-large" since it was a relative path.
         *
         *  @param searchPaths The array contains search paths.
         *  @see fullPathForFilename(const char*)
         *  @since v2.1
         *  In js:var setSearchPaths(var jsval);
         *  @lua NA
         */
        export function setSearchPaths ( searchPath:Array<string>):void;
        /**
         *  write a string into a file
         *
         * @param dataStr the string want to save
         * @param fullPath The full path to the file you want to save a string
         * @return bool True if write success
         */
        export function writeStringToFile (dataStr:string,fullPath:string):boolean;
        /**
         *  Sets the array that contains the search order of the resources.
         *
         *  @param searchResolutionsOrder The source array that contains the search order of the resources.
         *  @see getSearchResolutionsOrder(), fullPathForFilename(const char*).
         *  @since v2.1
         *  In js:var setSearchResolutionsOrder(var jsval)
         *  @lua NA
         */
        export function setSearchResolutionsOrder (searchResolutionsOrder:Array<string>):void;
        /**
         * Append search order of the resources.
         *
         * @see setSearchResolutionsOrder(), fullPathForFilename().
         * @since v2.1
         */
        export function addSearchResolutionsOrder (order:string,front:boolean):void;
        /**
